const items = $input.all();
const parsed = [];
const today = new Date().toISOString().split('T')[0];

for (const item of items) {
  let jobs = item.json;
  if (!Array.isArray(jobs)) {
    if (jobs && typeof jobs === 'object') jobs = Object.values(jobs);
    else continue;
  }
  for (const job of jobs) {
    // Skip the legal notice (first item) and items without URL
    if (!job || typeof job !== 'object' || !job.url || job.legal) continue;
    parsed.push({
      json: {
        job_id: String(job.id || ''),
        job_title: job.position || '',
        company: job.company || '',
        job_url: job.url || '',
        source: 'remoteok',
        location_text: job.location || 'Remote',
        salary: job.salary_min ? `$${job.salary_min}-$${job.salary_max}/yr` : '',
        description: (job.description || '') + ' ' + (Array.isArray(job.tags) ? job.tags.join(' ') : ''),
        posted_date: job.date || '',
        tags: Array.isArray(job.tags) ? job.tags.join(', ') : '',
        date_found: today
      }
    });
  }
}

return parsed.length > 0 ? parsed : [{ json: { _empty: true, source: 'remoteok', date_found: today } }];

