// Input: rows from Google Sheets (existing jobs)
// Access merged jobs via previous node reference
const existingRows = $input.all();
const allMergedItems = $('Merge All Job Sources').all();

// Build sets of existing URLs and company+title keys
const existingUrls = new Set();
const existingKeys = new Set();

for (const row of existingRows) {
  if (row.json.job_url) existingUrls.add(row.json.job_url.trim());
  if (row.json.company && row.json.job_title) {
    existingKeys.add(`${row.json.company}|${row.json.job_title}`.toLowerCase().trim());
  }
}

// Filter to only truly new jobs
const deduped = [];
const seenInBatch = new Set();
const seenKeysInBatch = new Set();

for (const item of allMergedItems) {
  // Skip empty placeholder items
  if (item.json._empty) continue;
  if (!item.json.job_url) continue;

  const url = item.json.job_url.trim();
  const key = `${item.json.company || ''}|${item.json.job_title || ''}`.toLowerCase().trim();

  if (existingUrls.has(url)) continue;
  if (existingKeys.has(key) && key !== '|') continue;
  if (seenInBatch.has(url)) continue;
  if (seenKeysInBatch.has(key) && key !== '|') continue;

  seenInBatch.add(url);
  seenKeysInBatch.add(key);
  deduped.push(item);
}

console.log(`Deduplicated: ${allMergedItems.length} total → ${deduped.length} new jobs`);
return deduped;

const items = $input.all();
const passed = [];
const rejected = [];

const REJECT_PATTERNS = [
  { pattern: /\bus[- ]only\b/i, reason: 'US only' },
  { pattern: /\bunited states only\b/i, reason: 'US only' },
  { pattern: /\bcanada[- ]only\b/i, reason: 'Canada only' },
  { pattern: /\buk[- ]only\b/i, reason: 'UK only' },
  { pattern: /\beu[- ]only\b/i, reason: 'EU only' },
  { pattern: /\beurope[- ]only\b/i, reason: 'Europe only' },
  { pattern: /\baustralia[- ]only\b/i, reason: 'Australia only' },
  { pattern: /must be (based|located|residing) in (the )?(us|uk|eu|europe|canada|australia)/i, reason: 'Must be based in restricted country' },
  { pattern: /must live in (the )?(us|uk|eu|europe|canada|australia)/i, reason: 'Must live in restricted country' },
  { pattern: /authorized to work in (the )?(us|uk|eu|canada|australia)/i, reason: 'Work authorization required' },
  { pattern: /must be authorized to work/i, reason: 'Work authorization required' },
  { pattern: /local work permit required/i, reason: 'Work permit required' },
  { pattern: /\bremote within (the )?(us|uk|eu|canada|australia|country)\b/i, reason: 'Remote within country only' },
  { pattern: /\bfixed us hours\b/i, reason: 'Fixed US hours' },
  { pattern: /\bfixed eu hours\b/i, reason: 'Fixed EU hours' },
  { pattern: /\bonsite\b/i, reason: 'Onsite required' },
  { pattern: /\bin-office\b/i, reason: 'In-office required' },
  { pattern: /office required/i, reason: 'Office required' },
  { pattern: /\bhybrid( role)?\b/i, reason: 'Hybrid role' },
  { pattern: /work from our (office|headquarters)/i, reason: 'Office required' },
  { pattern: /restricted to (the )?(us|uk|eu|canada|australia)/i, reason: 'Restricted to specific country' }
];

const STRONG_KEEP_PATTERNS = [
  /worldwide remote/i,
  /global remote/i,
  /work from anywhere/i,
  /fully remote.*anywhere/i,
  /\banywhere in the world\b/i,
  /international contractors? (accepted|welcome|ok)/i,
  /hires? (via|through) (deel|remote\.com|oyster|plane\.com)/i,
  /\beor (supported|available)\b/i,
  /contractor.*worldwide/i,
  /b2b contract/i,
  /distributed.*team/i
];

for (const item of items) {
  const text = [
    item.json.job_title || '',
    item.json.location_text || '',
    item.json.description || '',
    item.json.tags || ''
  ].join(' ');

  // Check for strong keep signals first
  let hasStrongKeep = false;
  for (const pat of STRONG_KEEP_PATTERNS) {
    if (pat.test(text)) {
      hasStrongKeep = true;
      break;
    }
  }

  if (hasStrongKeep) {
    passed.push(item);
    continue;
  }

  // Check reject patterns
  let rejectReason = '';
  for (const { pattern, reason } of REJECT_PATTERNS) {
    if (pattern.test(text)) {
      rejectReason = reason;
      break;
    }
  }

  if (rejectReason) {
    rejected.push({
      json: {
        ...item.json,
        reject_reason: rejectReason,
        date_rejected: new Date().toISOString().split('T')[0],
        _outcome: 'rejected_hard_filter'
      }
    });
  } else {
    passed.push(item);
  }
}

console.log(`Hard filter: ${passed.length} passed, ${rejected.length} rejected`);
return [passed, rejected];

