return $input.all().map(item => {
  try {
    // claude_response is the API response body; original job fields are preserved
    const claudeResp = item.json.claude_response || item.json;
    const textContent = claudeResp?.content?.[0]?.text || claudeResp?.content || '{}';

    // Extract JSON from Claude response
    const jsonMatch = typeof textContent === 'string'
      ? textContent.match(/\{[\s\S]*?\}/)
      : null;

    let parsed = {};
    if (jsonMatch) {
      try { parsed = JSON.parse(jsonMatch[0]); } catch(e) { parsed = {}; }
    }

    // Remove the raw claude_response from the output
    const jobData = { ...item.json };
    delete jobData.claude_response;

    return {
      json: {
        ...jobData,
        taiwan_eligible: parsed.taiwan_eligible || 'unclear',
        taiwan_reason: parsed.reason || 'Could not parse AI response',
        location_risk: parsed.location_risk || 'medium',
        timezone_risk: parsed.timezone_risk || 'medium',
        contractor_possible: parsed.contractor_possible || 'unclear',
        ai_decision: parsed.decision || 'manual_check'
      }
    };
  } catch(e) {
    const jobData = { ...item.json };
    delete jobData.claude_response;
    return {
      json: {
        ...jobData,
        taiwan_eligible: 'unclear',
        taiwan_reason: `Parse error: ${e.message}`,
        location_risk: 'medium',
        timezone_risk: 'medium',
        contractor_possible: 'unclear',
        ai_decision: 'manual_check'
      }
    };
  }
});

const ASYNC_KEEP = [
  { pattern: /\basync\b/i, score: 25, label: 'high' },
  { pattern: /\basynchronous\b/i, score: 25, label: 'high' },
  { pattern: /\bflexible hours\b/i, score: 20, label: 'high' },
  { pattern: /\bflexible schedule\b/i, score: 20, label: 'high' },
  { pattern: /\bdistributed team\b/i, score: 15, label: 'medium' },
  { pattern: /\bremote.?first\b/i, score: 10, label: 'medium' },
  { pattern: /\blow.?meeting\b/i, score: 20, label: 'high' },
  { pattern: /\bacross time zones?\b/i, score: 15, label: 'medium' },
  { pattern: /\bwork across timezones?\b/i, score: 20, label: 'high' },
  { pattern: /\bno meetings?\b/i, score: 25, label: 'high' }
];

const ASYNC_REJECT = [
  /\bstrict 9.?to.?5\b/i,
  /\bfixed (us|est|pst|cet|gmt) hours\b/i,
  /\bdaily live calls? required\b/i,
  /\bmust overlap full business day\b/i,
  /\bcore hours.{0,20}EST\b/i,
  /\bcore hours.{0,20}PST\b/i
];

const PRIMARY_ROLES = [
  /\bdata analyst\b/i,
  /\bdata scientist\b/i,
  /\bbusiness intelligence\b/i,
  /\bbi analyst\b/i,
  /\bmarketing analyst\b/i,
  /\bgrowth analyst\b/i,
  /\bai marketing\b/i,
  /\bai automation\b/i,
  /\bai workflow\b/i,
  /\bmartech\b/i,
  /\bperformance marketing analyst\b/i,
  /\bautomation specialist\b/i,
  /\bcreative strategist.{0,20}data\b/i
];

const ADJACENT_ROLES = [
  /\bdata engineer\b/i,
  /\banalytics engineer\b/i,
  /\bproduct analyst\b/i,
  /\bdigital marketing\b/i,
  /\bgrowth hacker\b/i,
  /\bseo specialist\b/i,
  /\bppc specialist\b/i,
  /\bgrowth marketing\b/i,
  /\becommerce analyst\b/i
];

return $input.all().map(item => {
  const text = [
    item.json.job_title || '',
    item.json.description || '',
    item.json.tags || '',
    item.json.location_text || ''
  ].join(' ');

  // === ASYNC SCORE ===
  let asyncScore = 0;
  let asyncLevel = 'unknown';
  let asyncRejected = false;

  for (const pat of ASYNC_REJECT) {
    if (pat.test(text)) { asyncRejected = true; break; }
  }

  if (!asyncRejected) {
    for (const { pattern, score, label } of ASYNC_KEEP) {
      if (pattern.test(text)) {
        if (score > asyncScore) { asyncScore = score; asyncLevel = label; }
      }
    }
    if (asyncLevel === 'unknown') asyncScore = 5; // neutral
  }

  // === ROLE FIT SCORE ===
  let roleScore = 0;
  let roleCategory = 'other';

  for (const pat of PRIMARY_ROLES) {
    if (pat.test(text)) { roleScore = 25; roleCategory = 'primary'; break; }
  }
  if (roleCategory === 'other') {
    for (const pat of ADJACENT_ROLES) {
      if (pat.test(text)) { roleScore = 15; roleCategory = 'adjacent'; break; }
    }
  }

  // === TAIWAN ELIGIBILITY SCORE ===
  let taiwanScore = 0;
  const locText = (item.json.location_text || '') + ' ' + (item.json.description || '');

  if (/worldwide|global remote|work from anywhere|\banywhere\b|contractor|eor|deel|remote\.com|oyster/i.test(locText)) {
    taiwanScore = 40;
  } else if (/\bapac\b/i.test(locText)) {
    taiwanScore = 30;
  } else if (item.json.taiwan_eligible === 'yes') {
    taiwanScore = 40;
  } else if (item.json.taiwan_eligible === 'unclear') {
    taiwanScore = 20;
  }

  // === SALARY SCORE ===
  let salaryScore = 0;
  const salaryStr = item.json.salary || '';
  const salaryNums = salaryStr.match(/\d[\d,]*/g);
  if (salaryNums && salaryNums.length > 0) {
    const maxVal = Math.max(...salaryNums.map(n => parseInt(n.replace(/,/g, ''))));
    // Normalize: if looks like annual ($60000) vs monthly ($5000)
    const isAnnual = maxVal > 20000;
    const monthly = isAnnual ? maxVal / 12 : maxVal;
    if (monthly >= 5000) salaryScore = 25;
    else if (monthly >= 3000) salaryScore = 15;
    else if (salaryStr) salaryScore = 10;
  }

  const totalScore = taiwanScore + asyncScore + roleScore + salaryScore;

  // === WHY GOOD FIT ===
  const reasons = [];
  if (taiwanScore >= 40) reasons.push('Clear global/worldwide eligibility');
  else if (taiwanScore >= 30) reasons.push('APAC-friendly role');
  if (asyncLevel === 'high') reasons.push('Strong async culture');
  else if (asyncLevel === 'medium') reasons.push('Flexible distributed team');
  if (roleCategory === 'primary') reasons.push('Direct match for Jerry\'s target roles');
  else if (roleCategory === 'adjacent') reasons.push('Adjacent to Jerry\'s background');
  if (salaryScore >= 25) reasons.push('Competitive salary');

  return {
    json: {
      ...item.json,
      async_level: asyncLevel,
      role_category: roleCategory,
      score: totalScore,
      taiwan_score: taiwanScore,
      async_score: asyncScore,
      role_score: roleScore,
      salary_score: salaryScore,
      why_good_fit: reasons.join('; ') || 'General remote match',
      application_status: 'new',
      notes: ''
    }
  };
});

return $input.all().map(item => {
  const resp = item.json.cover_letter_response;
  const text = resp?.content?.[0]?.text || 'Cover letter generation failed.';
  const jobData = { ...item.json };
  delete jobData.cover_letter_response;
  return { json: { ...jobData, cover_letter_draft: text } };
});

const items = $input.all();
const today = new Date().toLocaleDateString('en-US', { timeZone: 'Asia/Taipei', weekday: 'long', year: 'numeric', month: 'long', day: 'numeric' });

const highScore = items.filter(i => i.json._outcome === 'high_score').sort((a, b) => b.json.score - a.json.score);
const mediumScore = items.filter(i => i.json._outcome === 'medium_score').sort((a, b) => b.json.score - a.json.score);
const manualCheck = items.filter(i => i.json.ai_decision === 'manual_check' && (i.json.score || 0) >= 70);
const rejectedHard = items.filter(i => i.json._outcome === 'rejected_hard_filter');
const rejectedAI = items.filter(i => i.json._outcome === 'rejected_ai');
const rejectedScore = items.filter(i => i.json._outcome === 'rejected_score');

// Count rejection reasons
const usOnly = [...rejectedHard, ...rejectedAI].filter(i => /us only|united states/i.test(i.json.reject_reason || i.json.taiwan_reason || '')).length;
const euOnly = [...rejectedHard, ...rejectedAI].filter(i => /eu only|europe only/i.test(i.json.reject_reason || i.json.taiwan_reason || '')).length;
const hybrid = rejectedHard.filter(i => /hybrid|onsite|office/i.test(i.json.reject_reason || '')).length;
const tzRisk = rejectedAI.filter(i => i.json.timezone_risk === 'high').length;

let html = `<div style="font-family: Arial, sans-serif; max-width: 700px; margin: 0 auto;">
<h1 style="color: #1a1a2e;">Daily Taiwan Eligible Async Remote Jobs</h1>
<p style="color: #666;">Generated: ${today} (Taiwan Time)</p>
<hr/>
`;

if (highScore.length > 0) {
  html += `<h2 style="color: #e74c3c;">🔥 Top Matches (Score 85+)</h2>`;
  highScore.forEach((job, i) => {
    const j = job.json;
    html += `<div style="border:2px solid #e74c3c;border-radius:8px;padding:16px;margin-bottom:16px;">
  <h3 style="margin:0 0 8px 0;">${i + 1}. ${j.job_title}</h3>
  <table style="width:100%;border-collapse:collapse;">
    <tr><td style="padding:4px;font-weight:bold;width:160px">Company</td><td style="padding:4px">${j.company}</td></tr>
    <tr><td style="padding:4px;font-weight:bold">Score</td><td style="padding:4px"><strong>${j.score}/100</strong></td></tr>
    <tr><td style="padding:4px;font-weight:bold">Taiwan Eligible</td><td style="padding:4px">${j.taiwan_eligible}</td></tr>
    <tr><td style="padding:4px;font-weight:bold">Reason</td><td style="padding:4px">${j.taiwan_reason}</td></tr>
    <tr><td style="padding:4px;font-weight:bold">Async Level</td><td style="padding:4px">${j.async_level}</td></tr>
    <tr><td style="padding:4px;font-weight:bold">Timezone Risk</td><td style="padding:4px">${j.timezone_risk}</td></tr>
    <tr><td style="padding:4px;font-weight:bold">Salary</td><td style="padding:4px">${j.salary || 'Not listed'}</td></tr>
    <tr><td style="padding:4px;font-weight:bold">Why it fits Jerry</td><td style="padding:4px">${j.why_good_fit}</td></tr>
  </table>
  <p><a href="${j.job_url}" style="background:#e74c3c;color:white;padding:8px 16px;text-decoration:none;border-radius:4px">Apply Now</a></p>
</div>`;
  });
} else {
  html += `<p style="color:#888">No jobs scored 85+ today.</p>`;
}

if (mediumScore.length > 0) {
  html += `<h2 style="color: #27ae60;">✅ Good Matches (Score 70–84)</h2><ul>`;
  mediumScore.slice(0, 8).forEach(job => {
    const j = job.json;
    html += `<li style="margin-bottom:8px"><strong>${j.job_title}</strong> at ${j.company} <span style="color:#666">(Score: ${j.score})</span><br/><a href="${j.job_url}">${j.job_url}</a></li>`;
  });
  html += `</ul>`;
}

if (manualCheck.length > 0) {
  html += `<h2 style="color: #f39c12;">⚠️ Manual Check Needed</h2><ul>`;
  manualCheck.slice(0, 5).forEach(job => {
    const j = job.json;
    html += `<li style="margin-bottom:8px"><strong>${j.job_title}</strong> at ${j.company} (Score: ${j.score})<br/>Taiwan status: ${j.taiwan_eligible} — ${j.taiwan_reason}<br/><a href="${j.job_url}">${j.job_url}</a></li>`;
  });
  html += `</ul>`;
}

html += `<h2 style="color: #7f8c8d;">📊 Rejection Summary</h2>
<table style="border-collapse:collapse">
  <tr><td style="padding:4px">🇺🇸 US only</td><td style="padding:4px"><strong>${usOnly}</strong></td></tr>
  <tr><td style="padding:4px">🇪🇺 EU only</td><td style="padding:4px"><strong>${euOnly}</strong></td></tr>
  <tr><td style="padding:4px">🏢 Hybrid/Onsite</td><td style="padding:4px"><strong>${hybrid}</strong></td></tr>
  <tr><td style="padding:4px">⏰ Timezone risk</td><td style="padding:4px"><strong>${tzRisk}</strong></td></tr>
  <tr><td style="padding:4px">📉 Score below 70</td><td style="padding:4px"><strong>${rejectedScore.length}</strong></td></tr>
</table>
<p style="color:#888;font-size:12px;margin-top:24px">Total new jobs today: ${items.filter(i => !i.json._empty).length} | Passed filters: ${highScore.length + mediumScore.length}</p>
</div>`;

const totalGood = highScore.length + mediumScore.length;
const subject = highScore.length > 0
  ? `🔥 ${highScore.length} high-score Taiwan job${highScore.length > 1 ? 's' : ''} today + ${mediumScore.length} more`
  : totalGood > 0
    ? `✅ ${totalGood} Taiwan-eligible async job${totalGood > 1 ? 's' : ''} found today`
    : `Daily Taiwan Jobs: No strong matches today`;

return [{ json: { digest_html: html, digest_subject: subject } }];
